import React from 'react';
import { Link } from 'react-router-dom';
import { ArrowUpRight, Image as ImageIcon } from 'lucide-react';
import './BentoFeatures.css';

const BentoFeatures = ({ language }) => {
  const publicUrl = process.env.PUBLIC_URL || '';

  const content = {
    RU: {
      titleBold: 'Мы провели исследование и собрали полезности для вас.',
      titleNormal: 'Тюмень - это не деревня. Проверим?',
      researchTitle: 'Исследование', researchDesc: 'Стереотипы и реальность глазами иностранных студентов.',
      gastroTitle: 'Гастрономия', gastroDesc: 'Гид по лучшим заведениям',
      migrationTitle: 'Памятка', migrationDesc: 'Помощь в легализации',
      tipsTitle: 'Советы студентов', tipsDesc: 'Лайфхаки',
      galleryTitle: 'Галерея Тюмени', galleryDesc: '36 фотографий первого города Сибири'
    },
    EN: {
      titleBold: 'We conducted research and gathered useful tools for you.',
      titleNormal: 'Tyumen is not a village. Let’s check?',
      researchTitle: 'Research', researchDesc: 'Stereotypes and reality through the eyes of international students.',
      gastroTitle: 'Gastronomy', gastroDesc: 'Guide to the best places',
      migrationTitle: 'Guide', migrationDesc: 'Legalization support',
      tipsTitle: 'Student Tips', tipsDesc: 'Lifehacks',
      galleryTitle: 'Tyumen Gallery', galleryDesc: '36 photos of the first city in Siberia'
    }
  };

  const data = content[language];

  const handleMouseMove = (e) => {
    const card = e.currentTarget;
    const rect = card.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;
    const rotateX = ((y - centerY) / centerY) * -6; 
    const rotateY = ((x - centerX) / centerX) * 6;
    card.style.transition = 'none';
    card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale3d(1.02, 1.02, 1.02)`;
  };

  const handleMouseLeave = (e) => {
    const card = e.currentTarget;
    card.style.transition = 'transform 0.5s cubic-bezier(0.25, 1, 0.5, 1)'; 
    card.style.transform = `perspective(1000px) rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)`;
  };

  return (
    <section className="bento-features-section">
      <div className="container">
        <h2 className="bf-section-title">
          {data.titleBold} <br />
          <span className="bf-title-normal">{data.titleNormal}</span>
        </h2>
        
        <div className="bf-grid">
          
          <Link to="/research" id="tour-research" className="bf-card bf-research" onMouseMove={handleMouseMove} onMouseLeave={handleMouseLeave}>
            <div className="bf-content">
              <h3>{data.researchTitle}</h3>
              <p>{data.researchDesc}</p>
            </div>
            <img src={`${publicUrl}/images/kotak_research_first.webp`} alt="Кот исследование" className="bf-research-image" loading="lazy" />
            <ArrowUpRight className="bf-arrow" size={28} />
          </Link>

          {/* НОВАЯ КАРТОЧКА ГАСТРОНОМИИ СО ССЫЛКОЙ */}
          <a 
            href="https://bloodrose29.github.io/gastrogid-tymen/"
            target="_blank"
            rel="noopener noreferrer"
            id="tour-gastro" 
            className="bf-card bf-gastro" 
            onMouseMove={handleMouseMove} 
            onMouseLeave={handleMouseLeave}
          >
            <div className="bf-content">
              <h3>{data.gastroTitle}</h3>
              <p>{data.gastroDesc}</p>
            </div>
            <img src={`${publicUrl}/images/kotak_food.webp`} alt="Гастрономия" className="bf-gastro-image" loading="lazy" />
            <ArrowUpRight className="bf-arrow" size={28} />
          </a>

          <Link to="/migration" id="tour-guide" className="bf-card bf-migration" onMouseMove={handleMouseMove} onMouseLeave={handleMouseLeave}>
            <div className="bf-content">
              <h3>{data.migrationTitle}</h3>
              <p>{data.migrationDesc}</p>
            </div>
            <img src={`${publicUrl}/images/kotak_migrant_main.webp`} alt="Памятка Легализации" className="bf-migration-image" loading="lazy"/>
            <ArrowUpRight className="bf-arrow" size={24} />
          </Link>

          <Link to="/tips" id="tour-tips-card" className="bf-card bf-tips" onMouseMove={handleMouseMove} onMouseLeave={handleMouseLeave}>
            <div className="bf-content">
              <h3>{data.tipsTitle}</h3>
              <p>{data.tipsDesc}</p>
            </div>
            <img src={`${publicUrl}/images/kotak_lapa.webp`} alt="Лапа" className="bf-tips-image" loading="lazy"/>
            <ArrowUpRight className="bf-arrow" size={24} />
          </Link>

          <Link to="/gallery" id="tour-gallery" className="bf-card bf-gallery" onMouseMove={handleMouseMove} onMouseLeave={handleMouseLeave}>
            <div className="bf-content">
              <h3>{data.galleryTitle}</h3>
              <p>{data.galleryDesc}</p>
            </div>
            
            <div className="bf-gallery-images">
              <img src={`${publicUrl}/images/bg-1.jpg`} alt="Тюмень 1" loading="lazy"/>
              <img src={`${publicUrl}/images/bg-3.jpg`} alt="Тюмень 2" loading="lazy"/>
              <img src={`${publicUrl}/images/bg-7.jpg`} alt="Тюмень 3" loading="lazy"/>
              <div className="bf-gallery-more">
                <ImageIcon size={24} />
              </div>
            </div>

            <ArrowUpRight className="bf-arrow" size={28} />
          </Link>

        </div>
      </div>
    </section>
  );
};

export default BentoFeatures;